evidence.command:
$t = Join-Path $env:TEMP ('secpol_' + [guid]::NewGuid().ToString('N') + '.inf')
try {
  secedit /export /cfg $t /quiet | Out-Null
  if ($LASTEXITCODE -ne 0) { throw "secedit gagal (exit $LASTEXITCODE) - butuh Administrator" }
  $m = Select-String -Path $t -Pattern '^LockoutBadCount\s*=\s*(-?\d+)'
  if (-not $m) { throw 'LockoutBadCount tidak ditemukan pada hasil export' }
  $m.Matches[0].Groups[1].Value
} finally { Remove-Item $t -Force -ErrorAction SilentlyContinue }

